import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import {Navbar, Footer} from './components/layout.js';

function App(){
	return(
	<>
		<Navbar />
		<h2>Welcome to EcommDotComm!</h2>
		<Footer />
		</>
	)
}


const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
	<React.StrictMode>
		<App />
	</React.StrictMode>
);
